"use client";

import {
  type ButtonHTMLAttributes,
  createContext,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  use,
  useCallback,
  useId,
  useState,
} from "react";
import { cx } from "../utils/cx";
import { Slot } from "../utils/slot";

type CollapsibleContextValue = { open: boolean; toggle: () => void; contentId: string };
const CollapsibleContext = createContext<CollapsibleContextValue | null>(null);

function useCollapsible(part: string): CollapsibleContextValue {
  const ctx = use(CollapsibleContext);
  if (!ctx) throw new Error(`<${part}> must be inside <Collapsible>`);
  return ctx;
}

export type CollapsibleProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange"> & {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
};

/** One region that opens and closes. The content animates its height and stays mounted, so its state is kept. */
export function Collapsible({
  open: controlled,
  defaultOpen = false,
  onOpenChange,
  className,
  children,
  ...rest
}: CollapsibleProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const open = controlled ?? uncontrolled;
  const toggle = useCallback(() => {
    if (controlled === undefined) setUncontrolled(!open);
    onOpenChange?.(!open);
  }, [controlled, open, onOpenChange]);
  const contentId = useId();
  return (
    <CollapsibleContext value={{ open, toggle, contentId }}>
      <div {...rest} className={cx("hm-collapsible", className)} data-state={open ? "open" : "closed"}>
        {children}
      </div>
    </CollapsibleContext>
  );
}

export function CollapsibleTrigger({
  asChild,
  onClick,
  className,
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }) {
  const { open, toggle, contentId } = useCollapsible("CollapsibleTrigger");
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      {...(asChild ? {} : { type: "button" as const })}
      {...(rest as object)}
      className={cx("hm-collapsible-trigger", className)}
      aria-expanded={open}
      aria-controls={contentId}
      data-state={open ? "open" : "closed"}
      onClick={(e: MouseEvent<HTMLButtonElement>) => {
        onClick?.(e);
        if (!e.defaultPrevented) toggle();
      }}
    />
  );
}

export function CollapsibleContent({ className, children, ...rest }: HTMLAttributes<HTMLDivElement>) {
  const { open, contentId } = useCollapsible("CollapsibleContent");
  return (
    <div
      {...rest}
      id={contentId}
      className={cx("hm-collapsible-content", className)}
      data-state={open ? "open" : "closed"}
      inert={open ? undefined : true}
    >
      <div className="hm-collapsible-inner">{children}</div>
    </div>
  );
}
